<script setup lang="ts">
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import StorefrontNav from '@/components/StorefrontNav.vue';
import { isBackendConfigured } from '@/lib/supabase';
import { signInAdmin } from '@/services/admin-auth';
const router=useRouter(); const email=ref(''); const password=ref(''); const busy=ref(false); const error=ref('');
async function submit(){error.value='';busy.value=true;try{await signInAdmin(email.value.trim(),password.value);await router.replace('/admin')}catch(e){error.value=e instanceof Error?e.message:'Sign-in failed. Check your credentials and try again.'}finally{busy.value=false}}
</script>
<template><main class="login-page"><StorefrontNav/><section class="login-card"><p class="eyebrow">EVORYN · PRIVATE ACCESS</p><h1>Welcome<br/><em>behind the scenes.</em></h1><p class="subcopy">Sign in to curate the collection and manage availability.</p><div v-if="!isBackendConfigured" class="setup-notice"><strong>Admin access is not connected yet.</strong><p>Add the Supabase project URL and publishable key to the deployment environment, then apply the included database migration and provision an admin account.</p></div><form @submit.prevent="submit"><label>Email address<input v-model="email" type="email" autocomplete="username" required placeholder="you@evoryn.lk"/></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required placeholder="Your secure password"/></label><p v-if="error" class="error" role="alert">{{error}}</p><button :disabled="busy||!isBackendConfigured">{{busy?'Signing in…':'SIGN IN SECURELY'}} <span>↗</span></button></form><RouterLink to="/shop" class="return">Return to the collection</RouterLink></section></main></template>
